'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() {
  let resolve, reject;
  const promise = new Promise((a, b) => { resolve = a; reject = b; });
  return { promise, resolve, reject };
}

(async () => {
  // Older flight must not detach/overwrite a newer one.
  {
    const gates = [deferred(), deferred()];
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].resolve('old');
    assert.equal(await a, 'old');
    assert.equal(c.size, 0);
    const b2 = c.get('k'); // must join flight b
    gates[1].resolve('new');
    assert.equal(await b, 'new');
    assert.equal(await b2, 'new');
    assert.equal(calls, 2);
    assert.equal(await c.get('k'), 'new');
  }
  // set wins; old completion doesn't restart TTL; expiry starts new load.
  {
    let t = 0;
    const gate = deferred();
    let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (calls++ === 0 ? gate.promise : 'L2') });
    const a = c.get('k'); await tick();
    c.set('k', 'S');
    t = 5; gate.resolve('old');
    assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10;
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'L2');
    assert.equal(calls, 2);
  }
  // Rejection: shared, not cached, retry works; sync throw and non-Error reasons.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw 'boom'; return 'ok'; } });
    const p1 = c.get('k'), p2 = c.get('k');
    await assert.rejects(p1, r => r === 'boom');
    await assert.rejects(p2, r => r === 'boom');
    assert.equal(await c.get('k'), 'ok');
    assert.equal(calls, 2);
  }
  // Detached rejection doesn't detach newer flight.
  {
    const gates = [deferred(), deferred()];
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('x'));
    await assert.rejects(a);
    const b2 = c.get('k');
    gates[1].resolve('v');
    assert.equal(await b2, 'v'); assert.equal(await b, 'v'); assert.equal(calls, 2);
  }
  // load calling invalidate synchronously on its own key.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) c.invalidate(k); return 'v' + calls; } });
    assert.equal(await c.get('k'), 'v1');
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2');
  }
  // load reading its own key joins its flight.
  {
    let calls = 0, inner;
    const c = createCache({ now: () => 0, load: k => { calls++; inner = c.get(k); return 'v'; } });
    assert.equal(await c.get('k'), 'v');
    assert.equal(await inner, 'v');
    assert.equal(calls, 1);
  }
  // clear during load; repeated invalidations are separate barriers.
  {
    const gates = [deferred(), deferred(), deferred()];
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.clear();
    const b = c.get('k'); await tick();
    c.invalidate('k'); c.invalidate('k');
    const d = c.get('k'); await tick();
    gates[0].resolve(1); gates[1].resolve(2); gates[2].resolve(3);
    assert.deepEqual(await Promise.all([a, b, d]), [1, 2, 3]);
    assert.equal(await c.get('k'), 3);
    assert.equal(calls, 3);
  }
  // ttl 0: dedupe unsettled, never reuse settled.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++calls });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]);
    assert.equal(x, 1); assert.equal(y, 1);
    assert.equal(await c.get('k'), 2);
  }
  console.log('all scenarios ok');
})().catch(e => { console.error(e); process.exitCode = 1; });

