'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      const active = pending.get(key);
      if (active) return active.promise;
      const flight = { promise: null };
      // Only the flight still registered for key may detach itself or commit;
      // a detached flight just settles its own waiters.
      const settle = () => {
        if (pending.get(key) !== flight) return false;
        pending.delete(key);
        return true;
      };
      flight.promise = Promise.resolve().then(() => work()).then(value => {
        if (settle()) commit(value);
        return value;
      }, reason => {
        settle();
        throw reason;
      });
      pending.set(key, flight);
      return flight.promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

